/**
 * Replay of the shared test vectors (`docs/especificacao/vetores-de-teste/`),
 * generated by the Rust tool and committed: identity, envelope and message
 * vectors. Every vector must agree with this implementation, byte for byte.
 * The Noise, record and session vectors have their own replay.
 */

import { describe, expect, it } from "vitest";
import { CborMap, decodeCbor, encodeCbor, type CborValue } from "../src/cbor/index.js";
import { hexEncode } from "../src/encoding.js";
import {
  decodeClientEnvelope,
  decodeHandshakeStart,
  decodeHostEnvelope,
  encodeClientEnvelope,
  encodeHandshakeStart,
  encodeHostEnvelope,
  EnvelopeError,
  type ClientEnvelope,
  type HandshakeStart,
  type HostEnvelope,
} from "../src/envelope.js";
import { fingerprint } from "../src/fingerprint.js";
import { hostId } from "../src/hostId.js";
import {
  decodeMessage,
  decodePairRequest,
  encodeMessage,
  encodePairRequest,
  messageSender,
  type Direction,
  type Message,
} from "../src/index.js";
import { formatPairingUri, parsePairingUri } from "../src/pairingUri.js";
import { fromTyped, hex, toTyped, vectorsIn, type VectorError } from "./support/vectors.js";

// --- Identity ---

/** Reads the typed map of a pairing-URI vector into the invite fields. */
function inviteFrom(typed: unknown): Parameters<typeof formatPairingUri>[0] {
  const value = fromTyped(typed);
  if (!(value instanceof CborMap)) {
    throw new Error("invite is not a map");
  }
  const field = (key: string): CborValue => {
    const found = value.get(key);
    if (found === undefined) {
      throw new Error(`missing ${key}`);
    }
    return found;
  };
  return {
    major: field("v") as number,
    relayUrl: field("relay") as string,
    hostId: field("host") as string,
    hostKey: field("key") as Uint8Array,
    token: field("token") as Uint8Array,
    hostName: field("name") as string,
  };
}

describe("vectors: identidade", () => {
  const files = vectorsIn("identidade");
  it("has the vectors", () => {
    expect(files.length).toBeGreaterThanOrEqual(14);
  });
  for (const { name, json } of files) {
    it(name, () => {
      const funcao = json["funcao"];
      const valido = json["valido"] as boolean;
      const erro = json["erro"] as VectorError | null;
      switch (funcao) {
        case "host_id": {
          const key = fromTyped(json["entrada"]) as Uint8Array;
          expect(hostId(key)).toBe(json["saida"]);
          break;
        }
        case "fingerprint": {
          const key = fromTyped(json["entrada"]) as Uint8Array;
          expect(fingerprint(key)).toBe(json["saida"]);
          break;
        }
        case "pairing_uri_format": {
          expect(formatPairingUri(inviteFrom(json["entrada"]))).toBe(json["saida"]);
          break;
        }
        case "pairing_uri_parse": {
          const result = parsePairingUri(json["entrada"] as string);
          if (valido) {
            expect(result.ok).toBe(true);
            if (result.ok) {
              const { invite } = result;
              const expected = inviteFrom(json["saida"]);
              expect(invite.major).toBe(expected.major);
              expect(invite.relayUrl).toBe(expected.relayUrl);
              expect(invite.hostId).toBe(expected.hostId);
              expect(hexEncode(invite.hostKey)).toBe(hexEncode(expected.hostKey));
              expect(hexEncode(invite.token)).toBe(hexEncode(expected.token));
              expect(invite.hostName).toBe(expected.hostName);
            }
          } else {
            expect(result.ok).toBe(false);
            expect(erro?.camada).toBe("uri");
            if (!result.ok) {
              expect(result.error).toBe(erro?.codigo);
            }
          }
          break;
        }
        default:
          throw new Error(`unknown identity function ${String(funcao)}`);
      }
    });
  }
});

// --- Envelope ---

type Raiz = "host-envelope" | "client-envelope" | "handshake-start";

function decodeEnvelope(raiz: Raiz, bytes: Uint8Array): HostEnvelope | ClientEnvelope | HandshakeStart {
  switch (raiz) {
    case "host-envelope":
      return decodeHostEnvelope(bytes);
    case "client-envelope":
      return decodeClientEnvelope(bytes);
    case "handshake-start":
      return decodeHandshakeStart(bytes);
  }
}

function encodeEnvelope(raiz: Raiz, decoded: HostEnvelope | ClientEnvelope | HandshakeStart): Uint8Array {
  switch (raiz) {
    case "host-envelope":
      return encodeHostEnvelope(decoded as HostEnvelope);
    case "client-envelope":
      return encodeClientEnvelope(decoded as ClientEnvelope);
    case "handshake-start":
      return encodeHandshakeStart(decoded as HandshakeStart);
  }
}

/** The WebSocket close code (as text) the relay uses for a refused frame. */
function envelopeErrorCode(error: EnvelopeError): string {
  return error.reason === "frame-too-large" ? "1009" : "4004";
}

describe("vectors: envelope", () => {
  const files = vectorsIn("envelope");
  it("has the vectors", () => {
    expect(files.length).toBeGreaterThanOrEqual(38);
  });
  for (const { name, json } of files) {
    it(name, () => {
      const raiz = json["raiz"] as Raiz;
      const cbor = hex(json, "cbor_hex");
      if (json["valido"] === true) {
        // The typed value is the CBOR of the frame, and the frame decodes and re-encodes to itself.
        expect(toTyped(decodeCbor(cbor))).toEqual(json["valor"]);
        expect(hexEncode(encodeCbor(fromTyped(json["valor"])))).toBe(json["cbor_hex"]);
        const decoded = decodeEnvelope(raiz, cbor);
        expect(hexEncode(encodeEnvelope(raiz, decoded))).toBe(json["reencode_hex"] ?? json["cbor_hex"]);
      } else {
        const erro = json["erro"] as VectorError;
        expect(erro.camada).toBe("envelope");
        let thrown: unknown;
        try {
          decodeEnvelope(raiz, cbor);
        } catch (error) {
          thrown = error;
        }
        expect(thrown).toBeInstanceOf(EnvelopeError);
        expect(envelopeErrorCode(thrown as EnvelopeError)).toBe(erro.codigo);
      }
    });
  }
});

// --- Messages ---

/** The type of a message vector is its folder: `mensagens/<type>/<case>.json`. */
function messageTypeOf(name: string): Message["type"] | "pair-request" {
  return name.split("/")[1] as Message["type"] | "pair-request";
}

/** Directions to try for a message type: its sender, or both when either may send it. */
function directionsFor(type: Message["type"]): Direction[] {
  const sender = messageSender(type);
  return sender === "both" ? ["client", "host"] : [sender];
}

describe("vectors: mensagens", () => {
  const files = vectorsIn("mensagens");
  it("has the vectors", () => {
    expect(files.length).toBeGreaterThanOrEqual(240);
  });
  for (const { name, json } of files) {
    it(name, () => {
      const type = messageTypeOf(name);
      expect(json["raiz"]).toBe(type === "pair-request" ? "pair-request" : "message");
      const cbor = hex(json, "cbor_hex");

      if (json["valido"] === true) {
        // The typed value is the CBOR of the item (a non-canonical one is never valid).
        expect(toTyped(decodeCbor(cbor))).toEqual(json["valor"]);
        expect(hexEncode(encodeCbor(fromTyped(json["valor"])))).toBe(json["cbor_hex"]);
        const expected = json["reencode_hex"] ?? json["cbor_hex"];
        if (type === "pair-request") {
          expect(hexEncode(encodePairRequest(decodePairRequest(cbor)))).toBe(expected);
          return;
        }
        for (const from of directionsFor(type)) {
          const decoded = decodeMessage(cbor, from);
          expect(decoded.ok).toBe(true);
          if (decoded.ok) {
            expect(decoded.message.type).toBe(type);
            expect(hexEncode(encodeMessage(decoded.message))).toBe(expected);
          }
        }
      } else {
        const erro = json["erro"] as VectorError;
        expect(erro.camada).toBe("mensagem");
        expect(erro.codigo).toBe("protocol");
        if (type === "pair-request") {
          expect(() => decodePairRequest(cbor)).toThrow();
          return;
        }
        for (const from of directionsFor(type)) {
          expect(decodeMessage(cbor, from).ok).toBe(false);
        }
      }
    });
  }
});
